@Serializable
data class Tile(
    val id: String,
    val kind: String,
    val name: String,
    val poster: String? = null,
    val background: String? = null,
    val logo: String? = null,
    val posterShape: String,
    val releaseInfo: String? = null,
    /** 0.0 to 1.0 for items in progress. */
    val progress: Float? = null,
    /** Video to resume for Continue Watching tiles. */
    val videoId: String? = null,
    /** The IMDb rating the addon gave, as written ("8.4"). */
    val rating: String? = null,
    /** The IMDb and Rotten Tomatoes scores to show side by side: MDBList's, with the addon's own IMDb rating when MDBList has none. */
    val ratings: Ratings = Ratings(),
)

@Serializable
data class TitleDetails(
    val id: String,
    val kind: String,
    val name: String,
    val description: String? = null,
    val poster: String? = null,
    val background: String? = null,
    val logo: String? = null,
    val releaseInfo: String? = null,
    val runtime: String? = null,
    val genres: List<String> = emptyList(),
    val cast: List<String> = emptyList(),
    val directors: List<String> = emptyList(),
    /** The IMDb rating the addon gave, as written ("8.4"). */
    val rating: String? = null,
    /** The IMDb and Rotten Tomatoes scores to show side by side, as on tiles. */
    val ratings: Ratings = Ratings(),
    /** The title's IMDb page, for the IMDb score to link to; null for an id that is not IMDb's. */
    val imdbUrl: String? = null,
    /** Who the scores come from, a "Ratings from" row beside "Details from" ("IMDb and Rotten Tomatoes via MDBList"); null when MDBList gave none. */
    val ratingsFrom: String? = null,
    val source: String,
    /** Trailers the metadata names (YouTube), first is the main one. */
    val trailers: List<Trailer> = emptyList(),
)

@Serializable
data class TitleHeader(
    val state: TitleState,
    val details: TitleDetails? = null,
    val inLibrary: Boolean,
    val seasons: List<Int> = emptyList(),
    val selectedSeason: Int? = null,
    /** Episode (or the movie itself) the primary button resumes or starts. None while the next episode is not out yet (see `next_airs`). */
    val playTarget: PlayTarget? = null,
    /** The day the next episode comes out ("YYYY-MM-DD", as `Episode::released`) when it is not out yet: there is no play target, and the page says "Next episode airs <date>". */
    val nextAirs: String? = null,
    /** A movie the user watched (episodes carry their own flag); toggled with `setWatched` on the movie's id. */
    val watched: Boolean,
)

@Serializable
data class TitleSnapshot(
    val header: TitleHeader,
    val episodes: List<Episode> = emptyList(),
)

@Serializable
@JsonClassDiscriminator("state")
sealed interface TitleState {
    @Serializable
    @SerialName("loading")
    data object Loading : TitleState

    @Serializable
    @SerialName("ready")
    data object Ready : TitleState

    @Serializable
    @SerialName("failed")
    data class Failed(
        val reason: String,
    ) : TitleState
}

@Serializable
@JsonClassDiscriminator("kind")
sealed interface TitleUpdate {
    @Serializable
    @SerialName("header")
    data class Header(
        val header: TitleHeader,
    ) : TitleUpdate

    @Serializable
    @SerialName("episodes")
    data class Episodes(
        val diffs: List<ListDiff<Episode>> = emptyList(),
    ) : TitleUpdate
}

@Serializable
data class Trailer(
    val title: String,
    val youtubeId: String,
    /** The watch page, for apps that hand trailers to a browser or the YouTube app. */
    val url: String,
)

@Serializable
data class TraktImporting(
    val done: Int,
    val total: Int,
)

@Serializable
@JsonClassDiscriminator("phase")
sealed interface TraktLoginSnapshot {
    @Serializable
    @SerialName("starting")
    data object Starting : TraktLoginSnapshot

    @Serializable
    @SerialName("code")
    data class Code(
        val userCode: String,
        val url: String,
        val qr: String,
        val expiresMs: Long,
    ) : TraktLoginSnapshot

    @Serializable
    @SerialName("done")
    data class Done(
        val user: String,
    ) : TraktLoginSnapshot

    @Serializable
    @SerialName("expired")
    data object Expired : TraktLoginSnapshot

    @Serializable
    @SerialName("denied")
    data object Denied : TraktLoginSnapshot

    @Serializable
    @SerialName("notConfigured")
    data object NotConfigured : TraktLoginSnapshot

    @Serializable
    @SerialName("failed")
    data class Failed(
        val reason: String,
    ) : TraktLoginSnapshot
}

/** Trakt's side of a playback (`PlaybackSnapshot.trakt`). */
@Serializable(with = TraktPlayback.Serializer::class)
enum class TraktPlayback(
    val wire: String,
) {
    On("on"),
    Unmapped("unmapped"),
    Off("off"),
    ThisDeviceOff("thisDeviceOff"),

    /** A value from a newer core that this app does not know yet. */
    Unknown(""),
    ;

    object Serializer : FallbackEnumSerializer<TraktPlayback>("TraktPlayback", TraktPlayback.entries, TraktPlayback::wire, Unknown)
}

/** What one round did (`traktSync`). */
@Serializable
data class TraktReport(
    /** Rows read from Trakt. */
    val pulled: Int,
    /** Marks and resume points that changed the library. */
    val applied: Int,
    /** Writes Trakt took. */
    val pushed: Int,
    /** Writes still waiting. */
    val pending: Int,
    /** Items listed as unmapped in this round. */
    val unmapped: Int,
)

@Serializable
@JsonClassDiscriminator("state")
sealed interface TraktState {
    @Serializable
    @SerialName("connected")
    data object Connected : TraktState

    @Serializable
    @SerialName("failing")
    data class Failing(
        val sinceMs: Long,
        val reason: String,
    ) : TraktState

    @Serializable
    @SerialName("reconnect")
    data class Reconnect(
        val reason: String,
    ) : TraktState

    @Serializable
    @SerialName("off")
    data object Off : TraktState

    @Serializable
    @SerialName("thisDeviceOff")
    data object ThisDeviceOff : TraktState

    @Serializable
    @SerialName("notConfigured")
    data object NotConfigured : TraktState
}

/** The profile's Trakt status (`trakt` view). */
@Serializable
data class TraktStatus(
    val state: String,
    val sinceMs: Long? = null,
    val reason: String? = null,
    val user: String? = null,
    val lastOkMs: Long? = null,
    /** A status and Trakt's `error` field, never a body. */
    val lastError: String? = null,
    val pendingWrites: Int,
    /** The newest items Trakt could not take or give, newest first. */
    val unmapped: List<TraktUnmapped> = emptyList(),
    val importing: TraktImporting? = null,
    /** A record the app has not stored: store it, then `setTrakt(record)`. */
    val record: KeystoreRecord? = null,
) {
    // Holds keys or a token: never printed.
    override fun toString() = "TraktStatus(state=$state, sinceMs=$sinceMs, reason=$reason, user=$user, lastOkMs=$lastOkMs, lastError=$lastError, pendingWrites=$pendingWrites, unmapped=$unmapped, importing=$importing, record=${record?.let { "hidden" }})"
}

@Serializable
data class TraktUnmapped(
    val itemId: String,
    val name: String,
    val reason: String,
)

@Serializable
data class VersionRow(
    val key: String,
    /** "4K", "1440p", "1080p", "720p" or "SD"; when the release names no resolution, its source ("Blu-ray", "WEB-DL") or "Quality not stated". */
    val quality: String,
    /** Words, never emoji: "Dolby Vision", "HDR10", "Atmos", "5.1", "Remux". */
    val features: List<String> = emptyList(),
    val sizeBytes: Long? = null,
    val status: VersionStatus,
    /** Service ("Real-Debrid") or addon name. */
    val via: String,
    val releaseName: String,
    val languages: List<String> = emptyList(),
    val reasons: List<Reason> = emptyList(),
    val group: Group,
    val failoverCount: Int,
    /** What the row tells the user, with its numbers (3.7). */
    val line: ReasonLine,
    /** How it starts (3.2). */
    val sourceClass: SourceClass,
    /** Size over runtime after the pack guard; null when either is unknown. */
    val bitrateMbps: Float? = null,
    /** The sort key, for a details panel and tests. */
    val score: RankKey,
    /** "On this device": the version last played for this video, and this device holds its start at the resume point, so it starts with no peer (plans/player-polish.md 2b). Show it as the row's line. */
    val onDevice: String? = null,
)

/** What the ranking read for this view, for the header "This TV: 4K HDR, about 42 Mbit/s on Wi-Fi, 61 GB free". */
@Serializable
data class VersionsConditions(
    /** 2160, 1080, 720 or 480 (3.3). */
    val screenClass: Int,
    /** The screen shows HDR and the user wants it. */
    val hdr: Boolean,
    val network: Network,
    val http: Speed,
    val p2p: Speed,
    val freeBytes: Long? = null,
    val runtimeMin: Int? = null,
    val sizeLimitBytes: Long? = null,
    val minSeeders: Int,
    /** This build has the torrent engine. */
    val engine: Boolean,
    /** The profile has a streaming service account. */
    val account: Boolean,
    /** A torrent too big for the free space may play in a window here (plans/streaming-window.md 2.6). Off, such a row is too large for this storage, whatever its free space. */
    val window: Boolean = false,
)

@Serializable
data class VersionsSnapshot(
    /** What the ranking read: the screen, the connection, the disk, the title and the preferences in effect (4.2). */
    val conditions: VersionsConditions,
    /** Every addon answered, nothing is listed, and the hidden rows say why (3.11). */
    val blocked: BlockedVersions? = null,
    /** The one-time note when a pick taught Marquee something (3.9). */
    val note: LearnedNote? = null,
    val recommended: VersionRow? = null,
    val rows: List<VersionRow> = emptyList(),
    val hidden: HiddenSummary,
    val pendingAddons: List<String> = emptyList(),
    val slowAddons: List<String> = emptyList(),
    val failedAddons: List<String> = emptyList(),
    val done: Boolean,
    val frozen: Boolean,
    /** Every listed version is a swarm the engine would fetch whose trackers count one seeder or none: almost nobody is sharing this title right now, so say so before Play. Its attempt keeps the stall windows and the full deadline, but a swarm where no peer unchoked by the end of the first window (30 s) is let go then. */
    val nobodySharing: Boolean,
)

@Serializable
@JsonClassDiscriminator("kind")
sealed interface VersionStatus {
    @Serializable
    @SerialName("ready")
    data class Ready(
        val service: String? = null,
    ) : VersionStatus

    @Serializable
    @SerialName("torrent")
    data class Torrent(
        val seeds: Int? = null,
    ) : VersionStatus

    @Serializable
    @SerialName("needsDownload")
    data class NeedsDownload(
        val service: String? = null,
    ) : VersionStatus

    @Serializable
    @SerialName("direct")
    data object Direct : VersionStatus
}

@Serializable
data class WipePending(
    val debrid: Boolean,
)
